const champions = {};
for (const id in RC) {
  const r = RC[id];
  champions[id] = {
    key: r[0],
    title: r[1],
    name: r[2],
    icon: r[3].startsWith("#") ? DC + r[3].slice(1) + ".png" : r[3]
  };
}

const augments = {};
for (const id in RA) {
  const r = RA[id];
  augments[id] = {
    id,
    name: r[0],
    rarity: r[1],
    icon: r[2].startsWith("#") ? OA + r[2].slice(1) + OAS : r[2],
    hasDetail: Boolean(r[3]),
    detailId: r[3] ? id : ""
  };
}

const items = {};
for (const id in RI) {
  const r = RI[id];
  let icon = r[1];
  if (icon.startsWith("@o:")) icon = OI + icon.slice(3) + ".png";
  else if (icon.startsWith("@d:")) icon = DI + icon.slice(3) + ".png";
  items[id] = {
    id: r[2],
    detailId: r[2],
    name: r[0],
    icon
  };
}

const spells = {};
for (const id in RS) {
  const r = RS[id];
  spells[id] = {
    name: r[0],
    icon: DS + r[1] + ".png"
  };
}

